const examples={existing:{title:'FROM YOUR PROJECT FOLDER',code:'# Serve your Laravel application\nlaraserve serve ./my-app\n\n# Prefer plain HTTP? You’re in control.\nlaraserve serve ./my-app --http',note:'First use needs internet to download the runtime. Follow the terminal prompts to trust the local certificate.'},new:{title:'A FRESH LARAVEL PROJECT',code:'# Create an app with PHP 8.3\nlaraserve new my-app --php-version 8.3\n\n# Bring it online locally\nlaraserve serve my-app',note:'Creates the app with Composer. Frontend assets need your own Node tooling. PHP 8.3 switching is supported on Linux.'},build:{title:'FROM THE LARASERVE SOURCE DIRECTORY',code:'# Requires Go 1.21 or newer\nmake build\n\n# Run the small client\n./bin/laraserve serve /path/to/my-app',note:'Building does not embed or download runtimes. Copy bin/laraserve to a supported machine; tools download on first use.'}};
let selected='existing';const escapeHTML=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
document.querySelectorAll('[data-guide]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.guide;document.querySelectorAll('[data-guide]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));const example=examples[selected];document.getElementById('guide-title').textContent=example.title;document.getElementById('guide-code').innerHTML=example.code.split('\n').map(l=>l.startsWith('#')?`<span class="code-comment">${escapeHTML(l)}</span>`:escapeHTML(l)).join('\n');document.getElementById('guide-note').textContent=example.note;}));
document.querySelectorAll('[data-config]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-config]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});const inspect=button.dataset.config==='inspect';document.getElementById('config-code').innerHTML=inspect?'<span class="code-comment"># Check before downloading</span>\nlaraserve versions ./my-app\n\n<span class="code-comment"># Override for this run</span>\nlaraserve serve --php-version 8.3':'<span class="line-number">1</span> {\n<span class="line-number">2</span>   <span class="code-key">"php"</span>: <span class="code-value">"8.3"</span>,\n<span class="line-number">3</span>   <span class="code-key">"mysql"</span>: <span class="code-value">"8.0"</span>\n<span class="line-number">4</span> }';document.getElementById('config-note').textContent=inspect?'Resolved versions are remembered in private project state and reused while compatible with your app.':'Each MySQL version keeps its own data. Switching versions does not migrate an existing database.';}));
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}document.getElementById('copy-command').addEventListener('click',async()=>{const text=examples[selected].code;try{await navigator.clipboard.writeText(text);toast('Commands copied');}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const copied=document.execCommand('copy');area.remove();toast(copied?'Commands copied':'Select the commands to copy them');}});
document.querySelectorAll('[role=tab]').forEach(button=>button.addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp','ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')];let index=tabs.indexOf(button);index=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(['ArrowRight','ArrowDown'].includes(event.key)?1:-1)+tabs.length)%tabs.length;tabs[index].focus();tabs[index].click();}));
